const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const levels=['Basic 1','Basic 2','Intermediate 1','Intermediate 2','Advanced 1','Advanced 2'];
const names=['Aarav Rao','Anaya Mehta','Vihaan Shah','Ira Nair','Kabir Das','Myra Sen','Reyansh Jain','Siya Reddy','Arjun Patel','Diya Menon','Advik Kumar','Tara Iyer'];
const students=Array.from({length:84},(_,i)=>({id:'OD-'+String(1001+i),name:i<12?names[i]:`${['Aanya','Dhruv','Nila','Rishi','Kavya','Ishan','Anvi','Rudra','Meher','Yash','Sana','Om'][i%12]} ${['Sharma','Bhat','Gowda','Kapoor','Rao','Nair'][Math.floor(i/12)-1]}`,level:levels[Math.floor(i/14)],batch:'B'+String(i%12+1).padStart(2,'0'),coach:['Meera','Rohan','Priya','Arun'][i%4],age:7+i%10,gender:i%2?'Female':'Male',programme:"Children’s gymnastics",status:'Active',fee:i<66?'Paid':i<78?'Partial':'Overdue',attendance:i%7===0?'Absent':'Present',progress:40+i%55,consent:true}));
const batches=Array.from({length:12},(_,i)=>({id:'B'+String(i+1).padStart(2,'0'),level:levels[Math.floor(i/2)],coach:['Meera','Rohan','Priya','Arun'][i%4],time:['07:00','08:00','16:00','17:00','18:00','19:00'][i%6],days:i%2?'Tue · Thu · Sat':'Mon · Wed · Fri',capacity:8,filled:[8,8,8,7,7,7,7,6,7,7,6,6][i]}));
const coaches=['Meera','Rohan','Priya','Arun','Nisha','Dev','Kiran','Aditi','Sam','Neha'];
let leads=[{name:'Riya S.',source:'Website',programme:'Children’s gymnastics',status:'New',date:'03 Oct · 16:00'},{name:'Neel P.',source:'WhatsApp',programme:'Calisthenics',status:'Trial booked',date:'02 Oct · 18:00'},{name:'Avni R.',source:'Walk-in',programme:'Children’s gymnastics',status:'Attended',date:'01 Oct · 17:00'},{name:'Ishaan K.',source:'Campaign',programme:'Personal training',status:'New',date:'Not booked'},{name:'Maya D.',source:'Call',programme:'Adult gymnastics',status:'Enrolled',date:'30 Sep · 07:00'},{name:'Ved M.',source:'Referral',programme:'Children’s gymnastics',status:'Waitlist',date:'Preferred Saturday'}];
let messages=[{name:'Trial confirmation',type:'Operational',status:'Approved',trigger:'On booking',sent:36},{name:'Fee due reminder',type:'Operational',status:'Approved',trigger:'3 days before due',sent:18},{name:'Renewal reminder',type:'Operational',status:'Approved',trigger:'7 days before expiry',sent:12},{name:'Progress milestone',type:'Operational',status:'Approved',trigger:'Coach approval',sent:8},{name:'New programme invitation',type:'Marketing',status:'Draft',trigger:'Manual campaign',sent:0}];
const nav=[['overview','◈','Overview'],['students','▧','Students'],['admissions','◎','Admissions'],['batches','▦','Batches & timetable'],['coaches','♧','Coaches'],['attendance','✓','Attendance'],['skills','◇','Skills & progress'],['fees','₹','Fees & payments'],['communication','✉','Parent communication'],['media','▣','Photos & videos'],['reports','▥','Reports'],['parent','⌂','Parent portal'],['integrations','⌘','Integrations'],['settings','⚙','Settings & access']];
let route='overview',role='Admin',filter='',tab='';let audit=['Workspace opened'];
function badge(t){return `<span class="badge ${/Overdue|Absent|Needs|Failed/.test(t)?'red':/Partial|Pending|Practising|Waitlist|Draft/.test(t)?'warn':/Trial|In progress|Leave/.test(t)?'blue':''}">${esc(t)}</span>`}
function person(s){return `<div class="person"><span class="letters">${esc(s.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><b>${esc(s.name)}</b><small>${esc(s.id||s.source||'Coach')}</small></div></div>`}
function stat(a,b,c){return `<div class="stat"><span class="label">${a}</span><strong>${b}</strong><small>${c}</small></div>`}
function stats(a){return `<div class="stats">${a.map(x=>stat(...x)).join('')}</div>`}
function table(h,r){return `<div class="tablewrap"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.length?r.map(x=>`<tr>${x.map(y=>`<td>${y}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${h.length}" class="empty">No matching records. Try another search.</td></tr>`}</tbody></table></div>`}
function card(title,body,action=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`}
function head(k,title,desc,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function btn(t,fn,cl=''){return `<button class="${cl}" onclick="${fn}">${t}</button>`}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function log(t){audit.unshift(t);toast(t)}
function modal(title,body){$('#modalbody').innerHTML=`<h2>${title}</h2>${body}`;$('#modal').showModal()}
function options(a,sel){return a.map(x=>`<option ${x===sel?'selected':''}>${esc(x)}</option>`).join('')}
function field(label,name,type='text',value=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" required></label>`}
function select(label,name,a){return `<label>${label}<select name="${name}">${options(a)}</select></label>`}
function form(kind,title,fields){modal(title,`<form onsubmit="saveForm(event,'${kind}')"><div class="formgrid">${fields}</div><div class="modalfoot">${btn('Cancel',"$('#modal').close()") }<button class="primary" type="submit">Save changes</button></div></form>`)}
function exportCSV(kind=route){let data=kind==='students'?students:kind==='admissions'?leads:kind==='attendance'?students.map(s=>({id:s.id,name:s.name,batch:s.batch,status:s.attendance})):kind==='fees'?students.map(s=>({id:s.id,name:s.name,status:s.fee,charge:4000})):batches;const keys=Object.keys(data[0]);let csv=[keys.join(','),...data.map(x=>keys.map(k=>'"'+String(x[k]).replaceAll('"','""')+'"').join(','))].join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`one-dream-${kind}.csv`;a.click();URL.revokeObjectURL(a.href);toast('CSV downloaded')}
function toolbar(placeholder,extra=''){return `<div class="toolbar"><input type="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(filter)}" oninput="filter=this.value;renderContent()">${extra}</div>`}
function visibleStudents(){return students.filter(s=>(s.name+' '+s.id+' '+s.level+' '+s.batch).toLowerCase().includes(filter.toLowerCase()))}
function sidebar(){let items=role==='Parent'?nav.filter(x=>x[0]==='parent'):role==='Coach'?nav.filter(x=>['overview','students','batches','attendance','skills','media','coaches'].includes(x[0])):role==='Front desk'?nav.filter(x=>!['settings','integrations'].includes(x[0])):nav;$('#sidebar').innerHTML=`<div class="brand"><div class="mark">D</div><div><strong>ONE DREAM</strong><small>MOVE · LEARN · GROW</small></div></div><div class="navlabel">CENTRE MANAGEMENT</div><nav>${items.map(([id,ic,t])=>`<a href="#${id}" class="${route===id?'active':''}"><span class="ico">${ic}</span>${t}</a>`).join('')}</nav><div class="sidefoot">Gymnastics & Calisthenics<br><br>Powered by <b>myPAL</b></div>`}
function render(){route=location.hash.slice(1)||'overview';if(!nav.some(x=>x[0]===route))route='overview';sidebar();renderContent();document.body.classList.remove('nav-open')}
function renderContent(){let focus=document.activeElement?.type==='search',pos=document.activeElement?.selectionStart;$('#app').innerHTML=pages[route]()+`<div class="footerline">One Dream · Gymnastics & Calisthenics Fitness</div>`;if(focus){let el=$('#app input[type=search]');el?.focus();el?.setSelectionRange(pos,pos)}}
const pages={};
pages.overview=()=>head('Thursday, 01 October 2026','A good day to make progress.','Your centre at a glance. Keep students moving and operations in sync.',btn('New enquiry',"newLead()",'primary'))+stats([['Active placements','84','Across 12 batches'],['Seat occupancy','87.5%','12 seats available'],['Attendance this week','87.5%','294 of 336 scheduled records'],['Outstanding fees','₹48,000','18 accounts to follow up']])+`<div class="grid">${card('Batch occupancy',`<div class="bars">${levels.map((l,i)=>`<div class="barrow"><span>${l}</span><div class="track"><div class="fill" style="width:${[100,93.75,87.5,81.25,87.5,75][i]}%"></div></div><span>${[16,15,14,13,14,12][i]} / 16</span></div>`).join('')}</div>`, '<span class="badge">This month</span>')}${card('Today’s classes',batches.slice(0,4).map(b=>`<div class="schedule"><span class="time">${b.time}</span><div><b>${b.level}</b><p>${b.coach} · ${b.id} · ${b.filled} students</p></div>${badge('Scheduled')}</div>`).join(''),'<a class="btnlink" href="#batches">Timetable</a>')}</div><div class="grid equal">${card('Your attention, where it matters',`<div class="schedule"><span class="letters">06</span><div><b>Trial no-shows to reconnect with</b><p>Offer a suitable slot and record the outcome.</p><a href="#admissions" class="btnlink">Review admissions</a></div></div><div class="schedule"><span class="letters">18</span><div><b>Partial or unpaid fee accounts</b><p>Verify payments before sending a reminder.</p><a href="#fees" class="btnlink">Review fee ledger</a></div></div><div class="schedule"><span class="letters">03</span><div><b>Skill assessments need a coach review</b><p>Celebrate progress with an approved parent update.</p><a href="#skills" class="btnlink">Open skill tracker</a></div></div>`)}${card('Admissions this month',`<div class="chart">${[['Enquiries',60],['Booked',36],['Attended',30],['Enrolled',18]].map(([t,v])=>`<div style="height:${v/60*130}px"><b>${v}</b><span>${t}</span></div>`).join('')}</div><p style="margin-top:40px">30% enquiry-to-enrolment conversion this month.</p>`)}</div>`;
window.addEventListener('hashchange',()=>{filter='';tab='';render()});$('#role').onchange=e=>{role=e.target.value;location.hash=role==='Parent'?'parent':'overview';render()};window.addEventListener('DOMContentLoaded',render);
function newLead(){form('lead','New enquiry',field('Parent / student name','name')+select('Source','source',['Website','WhatsApp','Instagram','Walk-in','Call','Referral','Campaign'])+select('Programme','programme',["Children’s gymnastics",'Adult gymnastics','Calisthenics','Personal training','ADHD-focused development','Fitness / weight loss'])+field('Preferred trial date','date','date')+field('Phone number','phone','tel')+select('Communication permission','permission',['Operational updates only','Operational + marketing','Not recorded']))}
function newStudent(){form('student','Enrol a student',field('Student name','name')+select('Programme','programme',["Children’s gymnastics",'Adult gymnastics','Calisthenics','Personal training','ADHD-focused development','Fitness / weight loss'])+select('Level','level',levels)+select('Batch','batch',batches.map(b=>b.id))+field('Date of birth','dob','date')+field('Guardian name','guardian'))}
function saveForm(e,kind){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(kind==='lead')leads.unshift({...d,status:'New'});if(kind==='student')students.unshift({id:'OD-'+(1001+students.length),...d,coach:'Meera',age:9,status:'Active',fee:'Overdue',attendance:'Present',progress:0,consent:false});if(kind==='programme')plans.unshift({name:d.name,price:d.price,duration:d.duration});if(kind==='template')messages.push({name:d.name,type:d.type,status:'Draft',trigger:d.trigger,sent:0});$('#modal').close();log('Changes saved for this session');renderContent()}
pages.students=()=>head('Student records','Every student. One connected story.','Profiles, guardians, enrolment, progress and communication.',btn('Export CSV',"exportCSV('students')")+btn('Enrol student',"newStudent()",'primary'))+card('Student directory',toolbar('Search student, level, batch or ID')+table(['Student','Programme / level','Batch / coach','Status','Fees',''],visibleStudents().slice(0,30).map(s=>[person(s),`${s.programme}<small>${s.level}</small>`,`${s.batch}<small>${s.coach}</small>`,badge(s.status),badge(s.fee),btn('View profile',`profile('${s.id}')`,'small')]))+`<p class="footerline">Showing up to 30 of ${visibleStudents().length} matching records.</p>`);
function profile(id){let s=students.find(x=>x.id===id);modal(s.name,`<div class="person"><span class="letters">${s.id.slice(-2)}</span><div>${s.id}<small>${s.programme} · ${s.level}</small></div></div><div class="tabs" style="margin-top:20px">${['Overview','Health & consent','Fees','Progress','Media'].map(x=>btn(x,`profileTab('${id}','${x}')`,'small')).join('')}</div><div id="profilecontent"></div>`);profileTab(id,'Overview')}
function profileTab(id,t){let s=students.find(x=>x.id===id),c='';if(t==='Overview')c=`<div class="splitdetails"><div><h3>Student</h3><p>Age ${s.age} · ${s.gender||'Not recorded'}<br>${s.batch} · Coach ${s.coach}<br>Enrolled 01 Sep 2026</p></div><div><h3>Guardian & emergency</h3><p>Guardian contact not recorded<br>Emergency contact not recorded<br>Address: Bengaluru</p></div></div><label>Staff-only notes<textarea rows="3" style="width:100%">Review next level readiness with assigned coach.</textarea></label><div class="modalfoot">${btn('Save note',"log('Staff note saved for this session')",'primary')}${btn('Manage enrolment',`enrolment('${id}')`)}</div>`;if(t==='Health & consent')c=`<h3>Restricted health record</h3><p>Medical conditions: Not recorded<br>Allergies: Not recorded<br>Injury notes: Not recorded</p>${['Guardian consent form received','Operational WhatsApp permission','Marketing permission','Private media sharing permission','Public media approval'].map((x,i)=>`<label class="checkrow"><input type="checkbox" ${i<2?'checked':''}>${x}</label>`).join('')}`;if(t==='Fees')c=`${table(['Plan','Status','Balance'],[['Monthly · ₹4,000',badge(s.fee),s.fee==='Paid'?'₹0':s.fee==='Partial'?'₹2,000':'₹4,000']])}<p>Renewal date: 01 Nov 2026</p>${btn('View invoice',`invoice('${id}')`)}`;if(t==='Progress')c=`<h3>${s.progress}% assigned skills achieved</h3><div class="progress"><i style="width:${s.progress}%"></i></div><p>Attendance and assessment history</p>${table(['Date','Update','Coach'],[['30 Sep','Handstand · Practising','Meera'],['27 Sep','Pencil hold · Achieved','Meera'],['25 Sep','Attendance · Present','Meera']])}`;if(t==='Media')c=`<div class="media-thumb">▣</div><h3>Private progress clip</h3><p>No media file attached.</p>${badge('Guardian permission required')}`;$('#profilecontent').innerHTML=c}
function enrolment(id){modal('Manage enrolment',`<p>Manage enrolment for ${esc(students.find(s=>s.id===id).name)}.</p><div class="actions">${['Transfer','Hold','Renew','Exit'].map(x=>btn(x,`enrolAction('${id}','${x}')`)).join('')}</div>`)}
function enrolAction(id,a){let s=students.find(x=>x.id===id);if(a==='Transfer'){modal('Transfer batch',`<label>Destination batch<select id="transfer">${options(batches.map(b=>b.id),s.batch)}</select></label><div class="modalfoot">${btn('Confirm transfer',`students.find(s=>s.id==='${id}').batch=$('#transfer').value;$('#modal').close();log('Batch transferred for this session');renderContent()`,'primary')}</div>`);return}s.status=a==='Hold'?'On hold':a==='Exit'?'Exited':'Active';$('#modal').close();log(a+' recorded for this session');renderContent()}
pages.admissions=()=>head('Enquiries & trials','Turn interest into a first session.','Track sources, trial outcomes and enrolment handoffs.',btn('New enquiry',"newLead()",'primary'))+stats([['New enquiries','60','Monthly cohort'],['Trials booked','36','60% of enquiries'],['Trials attended','30','83.3% of bookings'],['Enrolled','18','30% of enquiries']])+`<div class="toolbar">${btn('Pipeline',"tab='pipeline';renderContent()",tab!=='list'?'primary':'')}${btn('List view',"tab='list';renderContent()",tab==='list'?'primary':'')}${btn('Export CSV',"exportCSV('admissions')")}</div>`+(tab==='list'?card('Lead records',table(['Name','Source','Programme','Status',''],leads.map((l,i)=>[person(l),l.source,l.programme,badge(l.status),btn('Manage',`leadDetail(${i})`,'small')]))):`<div class="kanban">${['New','Trial booked','Attended','Enrolled'].map(st=>`<section class="lane"><h3>${st} ${badge(leads.filter(l=>l.status===st).length)}</h3>${leads.map((l,i)=>l.status===st?`<div class="card"><h3>${esc(l.name)}</h3>${badge(l.source)}<p>${l.programme}<br>${l.date}</p>${btn('Manage enquiry',`leadDetail(${i})`,'small')}</div>`:'').join('')}</section>`).join('')}</div><div class="note">Waitlist: ${leads.filter(l=>l.status==='Waitlist').map(l=>esc(l.name)).join(', ')} · Capacity checked by programme, level and preferred slot.</div>`);
function leadDetail(i){let l=leads[i];modal('Enquiry · '+l.name,`<p>${l.programme} · ${l.source}</p><div class="formgrid"><label>Outcome<select id="leadstatus">${options(['New','Trial booked','Attended','No-show','Enrolled','Waitlist','Closed'],l.status)}</select></label><label>Trial slot<input id="leaddate" value="${esc(l.date)}"></label></div><div class="note">Enrolling a lead updates its status. Create its student profile through Students → Enrol student.</div><div class="modalfoot">${btn('Save outcome',`leads[${i}].status=$('#leadstatus').value;leads[${i}].date=$('#leaddate').value;$('#modal').close();log('Trial outcome updated');renderContent()`,'primary')}</div>`)}
pages.batches=()=>head('Batches & timetable','The right session for every level.','12 batches · 6 training levels · configurable capacity and coaches.',btn('Export timetable',"exportCSV('batches')"))+`<div class="tabs">${btn('Batch directory',"tab='';renderContent()",!tab?'selected':'')}${btn('Weekly timetable',"tab='week';renderContent()",tab?'selected':'')}</div>`+(tab==='week'?card('Weekly schedule',`<div class="week">${['Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<div class="day"><b>${d}</b>${batches.filter(b=>b.days.includes(d)).map(b=>`<div class="slot"><strong>${b.time} · ${b.id}</strong>${b.level}<br>${b.coach}<br>${b.filled} / ${b.capacity} seats</div>`).join('')}</div>`).join('')}</div>`):`<div class="mini-grid">${batches.map(b=>card(`${b.level} · ${b.id}`,`<p>${b.days}<br>${b.time} · Coach ${b.coach}</p><b>${b.filled} / ${b.capacity} seats</b><div class="progress"><i style="width:${b.filled/b.capacity*100}%"></i></div><p>${b.capacity-b.filled} open seats</p>${btn('Manage batch',`batchDetail('${b.id}')`,'small')}`)).join('')}</div>`);
function batchDetail(id){let b=batches.find(x=>x.id===id);modal('Batch '+id,`<div class="formgrid"><label>Coach<select id="bc">${options(coaches,b.coach)}</select></label><label>Capacity<input id="cap" type="number" min="${b.filled}" value="${b.capacity}"></label><label>Time<input id="bt" type="time" value="${b.time}"></label><label>Days<input id="bd" value="${b.days}"></label></div><div class="modalfoot">${btn('Save batch',`saveBatch('${id}')`,'primary')}</div>`)}
function saveBatch(id){let b=batches.find(x=>x.id===id),cap=Number($('#cap').value);if(cap<b.filled)return toast('Capacity cannot be below current enrolment');Object.assign(b,{capacity:cap,coach:$('#bc').value,time:$('#bt').value,days:$('#bd').value});$('#modal').close();log('Batch updated');renderContent()}
pages.coaches=()=>head('Team & shifts','A clear view of coach workload.','Manage full-time and part-time coaches, shifts and leave.')+stats([['Coaches','10','4 full-time · 6 part-time'],['Assigned batches','12','Across six levels'],['Today’s shifts','8','Scheduled shifts'],['Leave requests','2','Awaiting review']])+card('Coach directory',table(['Coach','Type','Assigned batches','Hours / week','Attendance',''],coaches.map((n,i)=>[person({name:n,id:'CO-'+(i+1)}),i<4?'Full-time':'Part-time',batches.filter(b=>b.coach===n).map(b=>b.id).join(', ')||'Cover / specialist',i<4?'30':'12',badge(i===6?'Leave':'Present'),btn('View shift',`coachDetail(${i})`,'small')])));
function coachDetail(i){modal(coaches[i]+' · Shift & leave',`<p>${i<4?'Full-time':'Part-time'} · Manual attendance / import fallback</p><div class="formgrid"><label>Attendance<select id="ca">${options(['Present','Absent','Late','Leave'])}</select></label><label>Shift<input type="text" value="07:00–12:00"></label><label>Leave date<input type="date"></label><label>Reason<input placeholder="Optional note"></label></div><div class="note">Manage coach attendance and shift records in the centre workspace.</div><div class="modalfoot">${btn('Save shift record',"$('#modal').close();log('Coach record saved for this session')",'primary')}</div>`)}
pages.attendance=()=>head('Attendance','A quick check-in. A complete history.','Mark student attendance by batch; exceptions feed parent follow-up.',btn('Export CSV',"exportCSV('attendance')")+btn('Save attendance',"log('Attendance saved for selected session')",'primary'))+`<div class="toolbar"><label>Date <input type="date" value="2026-10-01"></label><select aria-label="Filter attendance by batch" onchange="filter=this.value;renderContent()">${options(['All batches',...batches.map(b=>b.id)],filter||'All batches')}</select></div>`+card('Session register',table(['Student','Batch','Programme','Attendance',''],students.filter(s=>!filter||filter==='All batches'||s.batch===filter).slice(0,16).map(s=>[person(s),s.batch,s.level,`<select aria-label="Attendance for ${s.name}" onchange="students.find(s=>s.id==='${s.id}').attendance=this.value">${options(['Present','Absent','Late','Leave','Trial'],s.attendance)}</select>`,btn('History',`attendanceHistory('${s.id}')`,'small')]))+`<div class="note">Attendance statuses are separate; configure whether Late counts as attended in Settings.</div>`);
function attendanceHistory(id){modal('Attendance history',table(['Session','Status','Marked by'],[['30 Sep · 17:00',badge('Present'),'Meera'],['28 Sep · 17:00',badge('Absent'),'Meera'],['26 Sep · 17:00',badge('Present'),'Meera']])+btn('Preview absence update',"messagePreview('Absence update')"))}
const skills=['Jumps','Plank','Pencil hold','Back bend','Candle stand hold','Handstand','Front split','Back roll','Front roll split','Back roll split','Forward roll','Balance hold'];let skillStatus=skills.map((_,i)=>['Achieved','Achieved','Achieved','Practising','Achieved','In progress','Needs improvement','Not started','Achieved','Achieved','Achieved','Achieved'][i]);
pages.skills=()=>head('Skills & progression','Small milestones. Lasting confidence.','Digitise each movement, assessment and level-promotion review.',btn('Parent-ready report',"window.print()")+btn('Add skill',"form('skill','Add curriculum skill',field('Skill name','name')+select('Level','level',levels)+field('Prerequisite','prerequisite'))",'primary'))+`<div class="toolbar"><select aria-label="Student skill profile">${options(students.slice(0,12).map(s=>s.name))}</select><select aria-label="Training level" onchange="tab=this.value;renderContent()">${options(levels,tab||'Basic 1')}</select></div>`+stats([['Assigned skills',skills.length,'Assigned curriculum'],['Achieved',skillStatus.filter(x=>x==='Achieved').length,'Coach-assessed milestones'],['Completion',Math.round(skillStatus.filter(x=>x==='Achieved').length/skills.length*100)+'%','Achieved / assigned skills'],['Next review','08 Oct','Assigned coach: Meera']])+card((tab||'Basic 1')+' · Skill matrix',table(['Movement','Prerequisite','Status','Assessment',''],skills.map((s,i)=>[s,i?'Coach readiness check':'None',`<select aria-label="Status for ${s}" onchange="skillStatus[${i}]=this.value;renderContent()">${options(['Not started','In progress','Practising','Achieved','Needs improvement'],skillStatus[i])}</select>`,'30 Sep 2026',btn('Feedback',`skillDetail(${i})`,'small')]))+`<div class="note">Completion supports review; promotion requires the coach to confirm prerequisites and readiness.</div>`);
function skillDetail(i){modal(skills[i]+' · Assessment',`<p>Skill library → level → student assessment</p><div class="formgrid"><label>Assessment date<input type="date" value="2026-10-01"></label><label>Status<select id="ss">${options(['Not started','In progress','Practising','Achieved','Needs improvement'],skillStatus[i])}</select></label><label class="wide">Coach feedback<textarea rows="3">Continue form practice with coach supervision.</textarea></label></div><div class="note">Demonstration media can be linked with role-based visibility. No demonstration video attached.</div><div class="modalfoot">${btn('Save assessment',`skillStatus[${i}]=$('#ss').value;$('#modal').close();log('Assessment updated');renderContent()`,'primary')}</div>`)}
let plans=[{name:'Children’s gymnastics',price:4000,duration:'Monthly'},{name:'Adult gymnastics',price:4500,duration:'Monthly'},{name:'Calisthenics',price:3500,duration:'Monthly'},{name:'Personal training',price:1200,duration:'Single session'}];
pages.fees=()=>head('Fees & renewals','Every payment, accounted for.','Configurable packages, invoices, receipts and renewal follow-up.',btn('Export ledger',"exportCSV('fees')")+btn('Add fee plan',"form('programme','Configure fee plan',field('Programme','name')+field('Price (₹)','price','number')+select('Duration','duration',['Monthly','Quarterly','Half-yearly','Yearly','Personal training','Single session']))",'primary'))+stats([['Assessed charges','₹3,36,000','84 accounts × ₹4,000'],['Collected','₹2,88,000','Payments recorded'],['Outstanding','₹48,000','Partial + unpaid balances'],['Renewals due','12','In the next 7 days']])+`<div class="tabs">${['Ledger','Fee plans','Renewals'].map(x=>btn(x,`tab='${x}';renderContent()`,(tab||'Ledger')===x?'selected':'')).join('')}</div>`+(tab==='Fee plans'?`<div class="mini-grid">${plans.map(p=>card(esc(p.name),`<h1>₹${Number(p.price).toLocaleString('en-IN')}</h1><p>${p.duration}</p>${badge('Configurable')}<p>Admission fee and GST are configured separately.</p>`)).join('')}</div>`:card(tab==='Renewals'?'Renewal queue':'Student fee ledger',toolbar('Search student, level, batch or ID')+table(['Student','Plan','Status','Outstanding',''],visibleStudents().slice(tab==='Renewals'?0:60,tab==='Renewals'?12:84).map(s=>[person(s),'Monthly · ₹4,000',badge(s.fee),s.fee==='Paid'?'₹0':s.fee==='Partial'?'₹2,000':'₹4,000',btn('Invoice / payment',`invoice('${s.id}')`,'small')]))))+`<div class="note">Connect a payment gateway to collect online payments.</div>`;
function invoice(id){let s=students.find(x=>x.id===id);modal('Invoice · INV-'+id,`<div class="splitdetails"><div><h3>One Dream</h3><p>Invoice<br>${s.name} · ${s.id}</p></div><div><h3>October 2026</h3><p>Due: 01 Oct<br>Renewal: 01 Nov</p></div></div>${table(['Item','Amount'],[['Monthly gymnastics','₹4,000'],['Admission fee','₹0'],['GST (not configured)','₹0'],['Total','₹4,000']])}<p>Current state: ${badge(s.fee)}</p><label>Update payment status<select id="paystatus">${options(['Paid','Partial','Overdue','Refunded','Waived'],s.fee)}</select></label><div class="modalfoot">${btn('Print invoice',"window.print()")}${btn('Payment link',"toast('Connect a payment gateway to create payment links.')")}${btn('Record status',`students.find(s=>s.id==='${id}').fee=$('#paystatus').value;$('#modal').close();log('Ledger updated');renderContent()`,'primary')}</div>`)}
