let journeys=[['Trial-to-enrolment','Trial booked','Confirmation → 24-hour reminder → outcome follow-up','Trial families',true],['Welcome journey','Enrolment confirmed','Welcome → batch details → first-week check-in','New students',true],['Attendance recovery','3 consecutive absences','Parent check-in → staff review → return confirmation','At-risk attendance',false],['Renewal journey','7 days before expiry','Renewal reminder → due-date check → front-desk task','Renewals due',true],['Birthday celebration','Birthday approaching','Optional greeting → celebration invitation','Birthday month',false],['Milestone celebration','Coach approves achievement','Progress update → parent acknowledgement','Recently achieved',true],['Inactive-lead reactivation','30 days without enrolment','Relevant programme invite → staff callback','Inactive leads',false],['Referral invitation','Eligible active family','Share invitation → trial → enrolment validation','Active families',false]];
pages.engagement=()=>head('Engagement layer','Keep every family connected.','Segment your audience, build journeys and follow through on the response.',btn('Create campaign',"campaignForm()",'primary'))+stats([['Active journeys',journeys.filter(j=>j[4]).length,'Configured journeys'],['Renewal audience','12','Eligible contacts'],['Birthday audience','4','Birthdays this month'],['Staff follow-ups','7','Awaiting a human response']])+`<div class="tabs">${['Journeys','Audience segments','Campaigns','Referrals','Inbox'].map(x=>btn(x,`tab='${x}';renderContent()`,(tab||'Journeys')===x?'selected':'')).join('')}</div>`+engageBody();
function engageBody(){if(tab==='Audience segments')return `<div class="mini-grid">${[['New families',18,'Enrolled within 30 days'],['Trial families',36,'Trial booking recorded'],['Low attendance',6,'Below agreed attendance threshold'],['Renewals due',12,'Expiry in the next 7 days'],['Birthday month',4,'Voluntarily shared date'],['Inactive enquiries',24,'No enrolment after 30 days'],['Advanced levels',26,'Advanced 1 or Advanced 2'],['Marketing permitted',52,'Marketing permission recorded']].map(([n,c,r])=>card(n,`<h1>${c}</h1><p>${r}</p>${btn('Preview audience',`audience('${n}',${c})`,'small')}`)).join('')}</div><div class="note">A family can belong to more than one segment. Check messaging permission before outreach.</div>`;if(tab==='Campaigns')return card('Engagement campaigns',table(['Campaign','Audience','Status','Attempted','Replies',''],[['October trial invitation','Marketing-permitted leads',badge('Draft'),'0','0',btn('Preview',"messagePreview('October trial invitation')",'small')],['September parent check-in','Active families',badge('Completed'),'60','18',btn('Report',"campaignReport()",'small')],['Renewal follow-up','Due in 7 days',badge('Scheduled'),'0','0',btn('Preview',"messagePreview('Renewal reminder')",'small')]]))+`<div class="note">Connect WhatsApp Business to activate campaign delivery.</div>`;if(tab==='Referrals')return card('Family referral programme',`<div class="grid equal"><div><h3>Give a friend a first session</h3><p>An eligible family shares an invitation. A referral benefit is approved only after the qualifying enrolment is verified.</p><label>Benefit description<input style="width:100%" value="Complimentary skill workshop"></label><label class="checkrow"><input type="checkbox" checked>Require completed enrolment</label>${btn('Save referral rules',"log('Referral rules saved for this session')",'primary')}</div><div>${table(['Referral code','Referred family','Stage'],[['DREAM-A01','Rao family',badge('Trial booked')],['DREAM-B02','Mehta family',badge('Enrolled')],['DREAM-C03','Nair family',badge('New')]])}</div></div>`);if(tab==='Inbox')return card('Parent reply queue',table(['From','Conversation','Assigned to',''],[['Priya Rao','Can we move the trial to Saturday?','Front desk',btn('Open',"replyPreview('Trial reschedule')",'small')],['Neha Mehta','Please share the progress update.','Meera',btn('Open',"replyPreview('Progress request')",'small')],['Kiran Nair','Payment made; please verify.','Accounts',btn('Open',"replyPreview('Payment verification')",'small')]]));return `<div class="grid equal">${journeys.map((j,i)=>card(j[0],`<span class="badge">${j[3]}</span><p><b>Trigger:</b> ${j[1]}</p><p>${j[2]}</p><div class="actions">${btn(j[4]?'Enabled':'Paused',`journeys[${i}][4]=!journeys[${i}][4];renderContent()`,'small')}${btn('Preview journey',`journey(${i})`,'small')}</div>`)).join('')}</div>`}
function journey(i){let j=journeys[i];modal(j[0],`<div class="eyebrow">Journey steps</div><h3>${j[1]}</h3>${j[2].split(' → ').map((s,k)=>`<div class="schedule"><span class="letters">0${k+1}</span><div><b>${s}</b><p>${k?'Continue only when the relevant condition is met.':'Check contact permission and current record status.'}</p></div></div>`).join('')}<div class="note">Suppress opted-out recipients and stop follow-up when the objective is met. Sensitive replies move to staff.</div><div class="modalfoot">${btn('Check next step',"log('Next step reviewed. Connect WhatsApp to activate delivery.')",'primary')}</div>`)}
function audience(n,c){modal(n,`<h3>${c} matching contacts</h3><p>Audience rules: current enrolment / enquiry status, programme, milestone or selected date. Apply channel permission before activation.</p>${table(['Record','Permission'],[['Rao family',badge('Operational')],['Mehta family',badge('Marketing permitted')],['Nair family',badge('Review needed')]])}`)}
function campaignForm(){form('campaign','Create engagement campaign',field('Campaign name','name')+select('Audience','audience',['Trial families','Active families','Renewals due','Birthday month','Marketing permitted'])+select('Purpose','purpose',['Operational update','Marketing invitation'])+field('Schedule','date','datetime-local')+`<label class="wide">Message<textarea name="body" required rows="3">Hello {{parent_name}}, your next One Dream session is coming up. Reply if you need assistance.</textarea></label>`)}
function campaignReport(){modal('Parent check-in · Performance',stats([['Attempted','60','Campaign audience'],['Delivered','54','90% of attempted'],['Read','42','77.8% of delivered'],['Replies','18','30% of attempted']])+`<p>6 failed deliveries; review eligibility and contact details. Replies require categorisation and staff follow-up.</p>`)}
function replyPreview(t){modal(t,`<div class="note">Parent: ${t==='Trial reschedule'?'Could we attend this Saturday instead?':t==='Progress request'?'Please send the latest assessment.':'I made the payment today.'}</div><label>Reply<textarea rows="4" style="width:100%">Thank you. Our team will review your request and confirm.</textarea></label><div class="modalfoot">${btn('Assign to staff',"log('Conversation assigned for this session')")}${btn('Review reply',"log('Reply reviewed. Connect WhatsApp to send it.')",'primary')}</div>`)}
pages.communication=()=>head('WhatsApp & parent updates','Relevant updates. At the right moment.','Templates, reminders, permissions and delivery logs.',btn('New template',"form('template','Create message template',field('Template name','name')+select('Type','type',['Operational','Marketing'])+field('Trigger','trigger')+field('Message body','body'))",'primary'))+`<div class="tabs">${['Templates','Delivery log','Schedule','Permissions'].map(x=>btn(x,`tab='${x}';renderContent()`,(tab||'Templates')===x?'selected':'')).join('')}</div>`+(tab==='Delivery log'?card('Delivery log',table(['Update','Recipient','Status','Staff action'],[['Trial confirmation','Priya Rao',badge('Delivered'),'None'],['Renewal reminder','Neha Mehta',badge('Read'),'Check renewal'],['Absence update','Kiran Nair',badge('Failed'),'Verify contact'],['Batch change','Anita Shah',badge('Queued'),'Review queue']])):tab==='Schedule'?card('Scheduled reminders',table(['Trigger','Timing','Template','Enabled'],[['Trial booking','24 hours before','Trial reminder','Yes'],['Fees','3 days before + due date','Fee reminder','Yes'],['Renewal','7 days before expiry','Renewal reminder','Yes'],['Birthdays','On selected date','Birthday greeting','Optional'],['Holiday / batch change','Staff-selected time','Schedule update','Manual']])):tab==='Permissions'?card('Contact preferences',`<p>Keep operational updates, marketing permission and media approval separate.</p>${['Respect opt-outs','Require permission for marketing','Use approved templates outside service window','Allow staff override with audit note'].map(x=>`<label class="checkrow"><input type="checkbox" checked>${x}</label>`).join('')}${btn('Save preferences',"log('Communication preferences saved')")}`):card('Message templates',table(['Template','Purpose','Trigger','Status',''],messages.map(m=>[m.name,m.type,m.trigger,badge(m.status),btn('Preview',`messagePreview('${m.name}')`,'small')]))));
function messagePreview(t){modal(t,`<div style="background:#edf4ed;padding:24px;border-radius:12px"><b>ONE DREAM</b><p style="color:#254d43">Hello {{parent_name}},<br><br>${t.includes('Fee')?'Your fee payment is due on {{due_date}}. Please review your invoice.':t.includes('Trial')?'Your trial session is confirmed for {{session_date}} at {{session_time}}. We look forward to welcoming you.':t.includes('Absence')?'We missed {{student_name}} in today’s session. Let us know if you need any support.':t.includes('Renewal')?'Your plan renews on {{renewal_date}}. Contact the front desk to confirm your next term.':'Here is your latest One Dream update for {{student_name}}. Reply if you need assistance.'}<br><br>One Dream team</p></div><div class="note">Personalisation fields are filled from the recipient record. Connect WhatsApp to send this message.</div><div class="modalfoot">${btn('Review message',"log('Message reviewed. WhatsApp connection required for delivery.')",'primary')}</div>`)}
let mediaItems=[{name:'Handstand assessment',type:'Video',scope:'Private student',status:'Pending approval',tag:'OD-1001 · Skill'},{name:'Basic 1 practice session',type:'Photo',scope:'Private batch',status:'Approved',tag:'B01 · Training'},{name:'Centre showcase',type:'Video',scope:'Public marketing',status:'Needs consent',tag:'Event · Showcase'}];
pages.media=()=>head('Photos & videos','Celebrate progress, with permission.','Tag by student, batch, event or skill. Keep private and public media separate.',btn('Add media record',"mediaForm()",'primary'))+`<div class="mini-grid">${mediaItems.map((m,i)=>card(m.name,`<div class="media-thumb">${m.type==='Video'?'▷':'▣'}</div>${badge(m.status)}<p>${m.scope}<br>${m.tag}</p>${btn('Review permissions',`mediaDetail(${i})`,'small')}`)).join('')}</div><div class="note">Connect media storage to upload and share photos or videos.</div>`;
function mediaForm(){modal('Add media record',`<p>Select a file to add its details. Connect media storage to upload the file.</p><form onsubmit="event.preventDefault();mediaItems.push({name:$('#mn').value,type:'Photo',scope:'Private student',status:'Pending approval',tag:$('#mt').value});$('#modal').close();log('Media record added, file not uploaded');renderContent()"><div class="formgrid"><label>Title<input id="mn" required></label><label>Student / batch / event tag<input id="mt" required></label><label class="wide">Local file<input type="file" accept="image/*,video/*" required></label></div><div class="modalfoot"><button class="primary">Add record</button></div></form>`)}
function mediaDetail(i){modal('Media access · '+mediaItems[i].name,`<p>${mediaItems[i].scope}</p>${['Parental media consent verified','Coach approved content','Public marketing approval recorded'].map(x=>`<label class="checkrow"><input type="checkbox">${x}</label>`).join('')}<div class="note">Private student media is shared only with authorised guardians. Public use needs separate approval.</div><div class="modalfoot">${btn('Save review',`mediaItems[${i}].status='Review recorded';$('#modal').close();log('Review recorded');renderContent()`,'primary')}</div>`)}
pages.parent=()=>head('Parent portal','Hello, Aarav’s family.','A clear view of sessions, achievements and the next step.',btn('Ask the front desk',"replyPreview('Parent request')"))+stats([['Next session','02 Oct','17:00 · Basic 1'],['Attendance','92%','This month'],['Skills achieved','8 / 12','Assigned curriculum'],['Fee balance','₹0','October plan paid']])+`<div class="grid equal">${card('Aarav’s progress',`<div class="person"><span class="letters">AR</span><div><b>Aarav Rao</b><small>Basic 1 · Coach Meera</small></div></div><div class="progress"><i style="width:67%"></i></div><p>8 of 12 assigned skills achieved</p>${table(['Recent milestone','Coach feedback'],[['Pencil hold','Achieved · good form'],['Back bend','Practising · keep building control']])}${btn('Print progress report',"window.print()")}`)}${card('Your next sessions',batches.slice(0,3).map((b,i)=>`<div class="schedule"><span class="time">0${i+2} Oct</span><div><b>Basic 1 · 17:00</b><p>Coach Meera · 60 minutes</p></div>${badge('Scheduled')}</div>`).join(''))}</div><div class="grid equal">${card('Fees & receipts',`<h1>₹4,000</h1>${badge('Paid')}<p>October monthly package<br>Next renewal: 01 November 2026</p>${btn('View receipt',"invoice('OD-1001')")}`)}${card('Private media & preferences',`<div class="media-thumb">▣</div><p>Approved progress media will appear here.</p>${btn('Communication preferences',"parentPrefs()")}`)}</div>`;
function parentPrefs(){modal('Family preferences',`${['Operational WhatsApp updates','Progress milestone updates','Marketing invitations','Private media sharing','Public media use'].map((x,i)=>`<label class="checkrow"><input type="checkbox" ${i<2?'checked':''}>${x}</label>`).join('')}<div class="formgrid">${field('Birthday (optional)','birthday','date')}${field('Special day (optional)','special','date')}</div><div class="modalfoot">${btn('Save preferences',"$('#modal').close();log('Family preferences saved for this session')",'primary')}</div>`)}
pages.reports=()=>head('Reports & insights','Make the next decision clearer.','Filter by programme, batch, coach and reporting period.',btn('Print / save PDF',"window.print()")+btn('Export CSV',"exportCSV('students')",'primary'))+`<div class="toolbar"><select aria-label="Report programme">${options(['All programmes',"Children’s gymnastics",'Adult gymnastics','Calisthenics'])}</select><select aria-label="Report period">${options(['October 2026','September 2026'])}</select>${btn('Apply filters',"toast('Report view selected.')")}</div>`+stats([['Admissions','18','This month'],['Collection rate','85.7%','₹2,88,000 / ₹3,36,000'],['Average attendance','87.5%','This week'],['Enquiry conversion','30%','18 / 60 in same cohort']])+`<div class="grid equal">${card('Attendance by programme',`<div class="bars">${[['Children’s gymnastics',90],['Adult gymnastics',84],['Calisthenics',88],['Personal training',95]].map(([l,v])=>`<div class="barrow"><span>${l}</span><div class="track"><div class="fill" style="width:${v}%"></div></div><span>${v}%</span></div>`).join('')}</div>`)}${card('Available report views',table(['Report','Includes'],[['Student & batch','Attendance, capacity, waitlist'],['Coach','Working hours, leave, workload'],['Fees','Collections, dues, refunds, renewals'],['Progress','Skills by level and coach'],['Engagement','Lead conversion, reminder outcomes, campaign signals']]))}</div>`;
pages.integrations=()=>head('Integrations','A connected system, when you’re ready.','Review each connection’s purpose, data ownership and fallback.')+`<div class="grid equal">${[['WhatsApp Business API','Templates, reminders, campaign activity and replies','Dedicated number, permission and approved templates required.'],['Payment gateway','Payment links, verified transaction events and receipts','Choose provider and confirm refund and tax workflows.'],['Website & forms','New enquiries, trial requests and source attribution','Map consent and source fields into the student journey.'],['Future tools','Extension points for additional branches and tools','Define master record ownership and matching rules.']].map(([n,b,d])=>card(n,`${badge('Not connected')}<p>${b}</p><p>${d}</p>${btn('View data mapping',`mapping('${n}')`,'small')}`)).join('')}</div>`;
function mapping(n){modal(n+' · Proposed mapping',table(['Incoming field','Centre record'],[['External record ID','Source record reference'],['Phone / email','Duplicate-match candidate'],['Student / lead details','Profile or enquiry'],['Timestamp / event type','History and audit record']])+`<div class="note">Use a manual CSV import when the source has no supported API. Review duplicate matches before merging.</div>${btn('Check connection',"toast('Connection required before syncing records.')")}`)}
pages.settings=()=>head('Settings & access','Set the rules for your centre.','Programmes, privacy, permissions and operations.',btn('Save settings',"log('Settings saved for this session')",'primary'))+`<div class="tabs">${['Centre','Roles','Consent & security','Audit & backup','Decisions'].map(x=>btn(x,`tab='${x}';renderContent()`,(tab||'Centre')===x?'selected':'')).join('')}</div>`+settingsBody();
function settingsBody(){if(tab==='Roles')return card('Role-based access design',table(['Capability','Admin','Front desk','Coach','Parent'],[['Student records','Full','Operational','Assigned only','Own child'],['Fees & payments','Full','Manage','No','Own account'],['Skills & attendance','Full','View','Assigned batches','Own child'],['Health notes','Restricted','Emergency access','Need-to-know','Own child'],['Public media approval','Approve','Request','Request','Consent only'],['Settings & audit','Full','No','No','No']]))+`<div class="note">Connect identity management to enforce these access policies.</div>`;if(tab==='Consent & security')return card('Privacy and operational safeguards',`${['Communication and media consent stored separately','Restrict child and parent records by role','Audit sensitive record changes','Backups with recovery testing','Export access limited to authorised staff','Late counts as attended'].map(x=>`<label class="checkrow"><input type="checkbox" checked>${x}</label>`).join('')}<label class="checkrow">Repeated absence threshold <input type="number" value="3" min="1" style="width:75px"></label>`);if(tab==='Audit & backup')return card('Session audit trail',table(['Action','Scope'],audit.map(x=>[esc(x),'This browser session'])))+card('Backup & recovery',`<p>Connect storage to configure scheduled backups, retention rules and recovery.</p>${btn('Export records',"exportCSV('students')")}${btn('Reload workspace',"location.reload()")}`);if(tab==='Decisions')return card('Configuration checklist',table(['Decision','Current position'],[['Batch count and capacity','Approx. 12 × 8; validate timetable'],['Coach split / payroll','4 full-time + 6 part-time; payroll undecided'],['Parent access','Parent portal available'],['Payment provider','To confirm'],['Attendance capture','Manual mobile attendance'],['Media consent','Separate private / public approval'],['Branches','Single centre; additional branches configurable'],['Six-level curriculum','Detailed prerequisites to confirm'],['Fee / timetable migration','Source records and mapping to confirm']])) ;return `<div class="grid equal">${card('Centre details',`<div class="formgrid"><label class="wide">Centre name<input value="One Dream Gymnastics & Calisthenics Fitness"></label><label>Branch<input value="Main centre"></label><label>Timezone<select><option>Asia/Kolkata</option></select></label><label>Admission fee<input type="number" value="0"></label><label>GST rate (%)<input type="number" value="0"></label></div>`)}${card('Programmes & package durations',`<p>Children’s gymnastics · Adult gymnastics · Calisthenics · Personal training · ADHD-focused development · Fitness / weight loss</p><p>Monthly · Quarterly · Half-yearly · Yearly · Personal training · Single-session</p><div class="note">Fees are configurable by programme, duration and session type. No clinical outcomes are assumed.</div>`)}</div>`}
// Extend demo form handling without backend writes.
const baseSaveForm=saveForm;saveForm=function(e,k){if(k==='skill'){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));skills.push(d.name);skillStatus.push('Not started');$('#modal').close();log('Skill added to curriculum');renderContent();return}if(k==='campaign'){e.preventDefault();$('#modal').close();log('Campaign draft saved for this session.');return}baseSaveForm(e,k)};
// Optional browser tool for the same session-only attendance action.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'mark_demo_attendance',title:'Mark attendance',description:'Update attendance records in this browser session only. No external records or messages are changed.',inputSchema:{type:'object',properties:{studentId:{type:'string'},status:{type:'string',enum:['Present','Absent','Late','Leave','Trial']}},required:['studentId','status'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.studentId!=='string'||!['Present','Absent','Late','Leave','Trial'].includes(input.status))throw new Error('Invalid attendance input');const s=students.find(s=>s.id===input.studentId);if(!s)throw new Error('Unknown student');s.attendance=input.status;log('Attendance updated');renderContent();return {studentId:s.id,status:s.attendance,scope:'session-only'};}})).catch(()=>{});}catch{}}
