function channelIcon(type){const phone='<path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2z"/>';return `<span class="channel-icon ${type.toLowerCase()}"><svg viewBox="0 0 32 32" aria-label="${type}" role="img" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${type==='Instagram'?'<rect x="6" y="6" width="20" height="20" rx="6"/><circle cx="16" cy="16" r="5"/><circle cx="23" cy="9" r="1" fill="currentColor" stroke="none"/>':type==='WhatsApp'?'<path d="M7 25l-2 4 6-2a12 12 0 1 0-4-2z"/><g transform="translate(9 8) scale(.57)">'+phone+'</g>':'<g transform="translate(5 4)">'+phone+'</g>'}</svg></span>`}
