const oldEngageBody=engageBody;
function channelCard(ch,total,label,details){return `<section class="channel-card ${ch.toLowerCase()}"><div class="channel-top">${channelIcon(ch)}<b>${ch==='Call'?'Calls & follow-ups':ch}</b><span class="channel-tag">${ch==='Call'?'Staff managed':'Channel workspace'}</span></div><div class="channel-number">${total}<span>${label}</span></div><div class="channel-detail">${details}</div><button class="channel-open" onclick="tab='Inbox';channelFilter='${ch}';renderContent()">${ch==='Call'?'View call queue':'Open conversations'}</button></section>`}
let channelFilter='All channels';
pages.engagement=()=>head('OUTREACH · CONVERSATIONS · RETENTION','Engagement hub','Every enquiry has a next step. Every family stays connected.',btn('Create campaign',"campaignForm()",'primary'))+`<div class="engagement-banner"><div><span class="banner-kicker">TODAY’S PRIORITIES</span><h2>7 conversations need your team.</h2><p>3 new enquiries · 2 parent requests · 2 callbacks</p></div><div class="team-stack"><span>AS</span><span>MK</span><span>RK</span><div><b>Front desk & coaches</b><small>One shared follow-up queue</small></div></div>${btn('Review queue',"tab='Inbox';channelFilter='All channels';renderContent()",'lime')}</div><div class="channel-grid">${channelCard('WhatsApp','3','open conversations','Renewals, session updates & parent support')}${channelCard('Instagram','2','new enquiries','Reels, direct messages & programme interest')}${channelCard('Call','2','callbacks due','Assigned owners & scheduled follow-ups')}</div><div class="engage-summary"><span><b>84</b> student records</span><span><b>12</b> renewals approaching</span><span><b>4</b> birthdays this month</span><span><b>${journeys.filter(j=>j[4]).length}</b> configured journeys</span><a href="#reports">View centre reports</a></div><div class="tabs rich-tabs">${['Overview','Inbox','Journeys','Audience segments','Campaigns','Referrals'].map(x=>btn(x,`tab='${x}';renderContent()`,(tab||'Overview')===x?'selected':'')).join('')}</div>`+engageBody();
engageBody=function(){if(tab==='Inbox')return card('Shared conversation queue',`<div class="toolbar"><select aria-label="Conversation channel" onchange="channelFilter=this.value;renderContent()">${options(['All channels','WhatsApp','Instagram','Call'],channelFilter)}</select><span class="muted">${conversations.filter(c=>channelFilter==='All channels'||c.channel===channelFilter).length} open conversations</span></div>${conversationTable(conversations.filter(c=>channelFilter==='All channels'||c.channel===channelFilter))}`);if(tab==='Campaigns')return card('Campaign performance',`<p>Separate message activity from enrolment outcomes. Review replies before scheduling the next touchpoint.</p>${table(['Campaign','Channel / audience','Attempted','Delivered','Replies','Status'],campaignRows.map(r=>[r[0],r[1]+'<small>'+r[2]+'</small>',r[3],r[4],r[5],badge(r[6])]))}`);if(tab==='Journeys')return `<div class="grid equal">${journeys.map((j,i)=>`<section class="card journey-rich"><div class="cardhead"><div class="journey-icon">${channelIcon(i===6?'Instagram':'WhatsApp')}</div>${badge(j[4]?'Enabled':'Paused')}</div><h2>${j[0]}</h2><p>${j[3]} · ${j[1]}</p><div class="journey-steps">${j[2].split(' → ').map((x,k)=>`<div><span>${k+1}</span>${x}</div>`).join('')}</div><div class="journey-bottom"><span>Owner: ${i%2?'Front desk':'Assigned coach'}</span>${btn('Manage journey',`journey(${i})`,'small')}</div></section>`).join('')}</div>`;if(tab&&tab!=='Overview')return oldEngageBody();return `<div class="grid engagement-layout">${card('Conversations to pick up',conversationTable(conversations.slice(0,4)),btn('View all 7',"tab='Inbox';renderContent()",'small'))}${card('Team activity',`<div class="activity-list"><div><i class="wa-dot"></i><small>14:18 · Instagram</small><b>Priya asked about a beginner trial</b><p>Assigned to Ananya for a suitable Saturday slot.</p></div><div><i class="purple-dot"></i><small>13:36 · WhatsApp</small><b>Sneha requested a renewal link</b><p>Kavitha to verify the October package.</p></div><div><i class="blue-dot"></i><small>12:48 · Call</small><b>Nikhil requested an evening callback</b><p>Rohan · Today at 18:30.</p></div><div><i class="orange-dot"></i><small>11:15 · Attendance</small><b>Reyansh returns next Monday</b><p>Confirm return date and regular batch.</p></div></div>`)}</div><div class="grid equal">${card('Audience by next action',`<div class="audience-row"><span class="audience-glyph">01</span><div><b>Trial follow-ups</b><p>Attended a session, not yet enrolled</p></div><b>12</b></div><div class="audience-row"><span class="audience-glyph">02</span><div><b>Renewals approaching</b><p>Plan expires within seven days</p></div><b>12</b></div><div class="audience-row"><span class="audience-glyph">03</span><div><b>Attendance check-ins</b><p>Three consecutive sessions missed</p></div><b>6</b></div>${btn('Explore segments',"tab='Audience segments';renderContent()",'small')}`)}${card('Upcoming touchpoints',`<div class="schedule"><span class="date-chip">02<small>OCT</small></span><div><b>Rahul’s first calisthenics session</b><p>18:00 · Confirm what to bring and arrival time.</p>${badge('Trial confirmation')}</div></div><div class="schedule"><span class="date-chip">03<small>OCT</small></span><div><b>Saturday beginner enquiries</b><p>Check available seats before confirming trial slots.</p>${badge('Front desk follow-up')}</div></div><div class="schedule"><span class="date-chip">08<small>OCT</small></span><div><b>Basic 1 progress reviews</b><p>Coach sign-off before sharing updates with parents.</p>${badge('Progress milestone')}</div></div>`)}</div>`};
function conversationTable(list){return table(['Family / enquiry','Latest message','Owner / next step',''],list.map(c=>[`${person({name:c.name,id:c.child})}<div class="channel-inline">${channelIcon(c.channel)}${c.channel} · ${c.time}</div>`,`<b>${c.topic}</b><small class="message-excerpt">${esc(c.message)}</small>`,`${badge(c.state)}<small>${c.owner}</small>`,btn('Open',`openConversation(${conversations.indexOf(c)})`,'small')]))}
function openConversation(i){let c=conversations[i];modal(c.name,`<div class="conversation-meta">${channelIcon(c.channel)}<div><b>${c.channel} · ${c.topic}</b><p>${c.child} · ${c.source}</p></div></div><div class="chat-date">TODAY · ${c.time}</div><div class="chat-bubble">${esc(c.message)}</div><div class="next-action"><b>Next action</b><p>${c.next}</p><small>${c.owner}</small></div><label>Response<textarea id="responseDraft" rows="3" style="width:100%;margin-top:8px" placeholder="Write a response for the family…"></textarea></label><div class="modalfoot">${btn('Save response draft',"log('Response draft retained for this session')")}${btn('Review channel setup',"$('#modal').close();location.hash='integrations'",'primary')}</div>`)}
